   *Precondition: Required inputs are present, referenced data is valid, and the action is allowed by business rules.
   *Postcondition: The system applies the requested outcome, keeps data consistent, and returns the defined result.*/
  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: Item) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i:Item|i.Barcode=barcode)",
    }).build().pass;
    let currentOrder: OrderProduct = l({
      logic: () =>
        getRepository(OrderProduct).find(
          (o: OrderProduct) =>
            l({
              logic: () => o.OrderStatus === OrderStatus.NEW,
              description: "o.OrderStatus=OrderStatus::NEW",
            }).build().pass,
        ),
      description:
        "OrderProduct.allInstance()->any(o:OrderProduct|o.OrderStatus=OrderStatus::NEW)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(item) === false,
        description: "item.oclIsUndefined()=false",
      })
        .and({
          logic: () => quantity > 0,
          description: "quantity>0",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(currentOrder) === false,
          description: "currentOrder.oclIsUndefined()=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newEntry: OrderEntry;
    return l({
      execute: () => (newEntry = new OrderEntry()),
      description: "newEntry.oclIsNew()",
    })
      .and({
        execute: () => (newEntry.Quantity = quantity),
        description: "newEntry.Quantity=quantity",
      })
      .and({
        execute: () => (newEntry.SubAmount = item.OrderPrice * quantity),
        description: "newEntry.SubAmount=item.OrderPrice*quantity",
      })
      .and({
        execute: () => (newEntry.Item = item),
        description: "newEntry.Item=item",
      })
      .and({
        execute: () => getRepository(OrderEntry).push(newEntry),
        description: "OrderEntry.allInstance()->includes(newEntry)",
      })
      .and({
        execute: () => currentOrder.ContainedEntries.push(newEntry),
        description: "currentOrder.ContainedEntries->includes(newEntry)",
      })
      .and({
        execute: () =>
          (currentOrder.Amount = currentOrder.Amount + newEntry.SubAmount),
        description:
          "currentOrder.Amount=currentOrder.Amount+newEntry.SubAmount",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
"},"contract":"Contract CoCoMEOrderProducts::orderItem(barcode: Integer,quantity: Integer): Boolean {
	definition:
		item: Item = Item.allInstance()->any(i: Item|i.Barcode = barcode),
		currentOrder: OrderProduct = OrderProduct.allInstance()->any(o: OrderProduct|o.OrderStatus = OrderStatus::NEW)
	precondition:
		item.oclIsUndefined() = false and
		quantity>0 and
		currentOrder.oclIsUndefined() = false
	postcondition:
		let newEntry: OrderEntry in
		newEntry.oclIsNew() and
		newEntry.Quantity = quantity and
		newEntry.SubAmount = item.OrderPrice*quantity and
		newEntry.Item = item and
		OrderEntry.allInstance()->includes(newEntry) and
		currentOrder.ContainedEntries->includes(newEntry) and
		currentOrder.Amount = currentOrder.Amount+newEntry.SubAmount and
		result = true
}","typescriptErrors":[]}}
