          (c: BookCopy) =>
            l({
              logic: () => c.Barcode === barcode,
              description: "c.Barcode=barcode",
            }).build().pass,
        ),
      description: "BookCopy.allInstance()->any(c:BookCopy|c.Barcode=barcode)",
    }).build().pass;
