  makeReservation(uid: string, barcode: string): boolean {
    /*Definition Start*/
    let user: User = l({
      logic: () =>
        getRepository(User).find(
          (u: User) =>
            l({
              logic: () => u.UserID === uid,
              description: "u.UserID=uid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(u:User|u.UserID=uid)",
    }).build().pass;
    let copy: BookCopy = l({
      logic: () =>
        getRepository(BookCopy).find(
          (c: BookCopy) =>
            l({
              logic: () => c.Barcode === barcode,
              description: "c.Barcode=barcode",
            }).build().pass,
        ),
      description: "BookCopy.allInstance()->any(c:BookCopy|c.Barcode=barcode)",
    }).build().pass;
