          description: "copy.oclIsUndefined()=false",
        })
        .and({
          logic: () => user.BorrowStatus === BorrowStatus.NORMAL,
          description: "user.BorrowStatus=BorrowStatus::NORMAL",
        })
        .and({
          logic: () => copy.Status === CopyStatus.LOANED,
          description: "copy.Status=CopyStatus::LOANED",
        })
        .and({
          logic: () => copy.IsReserved === false,
          description: "copy.IsReserved=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (reserve = new Reserve()),
      description: "reserve.oclIsNew()",
    })
      .and({
        execute: () => (reserve.IsReserveClosed = false),
        description: "reserve.IsReserveClosed=false",
      })
      .and({
        execute: () => (reserve.ReservedCopy = copy),
        description: "reserve.ReservedCopy=copy",
      })
      .and({
        execute: () => (reserve.ReservedUser = user),
        description: "reserve.ReservedUser=user",
      })
      .and({
        execute: () => copy.ReservationRecord.push(reserve),
        description: "copy.ReservationRecord->includes(reserve)",
      })
      .and({
        execute: () => user.ReservedBook.push(reserve),
        description: "user.ReservedBook->includes(reserve)",
      })
      .and({
        execute: () => (copy.IsReserved = true),
        description: "copy.IsReserved=true",
      })
      .and({
        execute: () => getRepository(Reserve).push(reserve),
        description: "Reserve.allInstance()->includes(reserve)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
